solution.javascript:
var climbStairs = function(n) {
    let waysTwoBack = 1;
    let waysOneBack = 1;
    for (let step = 2; step <= n; step++) {
        const next = waysTwoBack + waysOneBack;
        waysTwoBack = waysOneBack;
        waysOneBack = next;
    }
    return waysOneBack;
};

