class Solution:
    def climbStairs(self, n: int) -> int:
        ways_two_back = 1
        ways_one_back = 1

        for step in range(2, n + 1):
            ways_two_back, ways_one_back = (
                ways_one_back,
                ways_two_back + ways_one_back
            )

        return ways_one_back
